+++ b/bindings/benchmarks/python_boundary.py
@@ -0,0 +1,117 @@
+# Copyright 2026 Nowledge
+# SPDX-License-Identifier: Apache-2.0
+
+"""Ordinary eager-dict Python baseline; no engine/binding behavior overrides."""
+
+import json
+import resource
+import sys
+import time
+import importlib.util
+from importlib.machinery import ExtensionFileLoader
+
+# The driver passes the hashed ordinary or instrumented extension explicitly.
+# This replacement is local to the benchmark process.
+if len(sys.argv) == 3:
+    loader = ExtensionFileLoader("hawdb._hawdb", sys.argv[2])
+    spec = importlib.util.spec_from_file_location("hawdb._hawdb", sys.argv[2], loader=loader)
+    native = importlib.util.module_from_spec(spec)
+    spec.loader.exec_module(native)
+    sys.modules["hawdb._hawdb"] = native
+
+import hawdb
+from checksum import Checksum
+
+from hawdb import _hawdb as native
+
+
+def native_delta(before, after):
+    result = {key: after[key] - before[key] for key in before
+              if key not in ("live_requested_bytes", "process_peak_requested_bytes")}
+    result["live_requested_bytes_before"] = before["live_requested_bytes"]
+    result["live_requested_bytes_after"] = after["live_requested_bytes"]
+    result["process_peak_requested_bytes"] = after["process_peak_requested_bytes"]
+    result["scope"] = "Rust allocator requests, excluding foreign heap/rounding/non-Rust workspace"
+    return result
+
+
+def run(job):
+    db = hawdb.open() if job["backend"] == "memory" else hawdb.open(job["path"])
+    phase = "setup"
+    try:
+        setup = time.perf_counter_ns()
+        db.execute("CREATE INDEX ON :Boundary(id)")
+        if job["case"] in ("select", "point", "wide"):
+            for offset in range(0, len(job["rows"]), 512):
+                db.execute(job["insert_bulk"], {"rows": job["rows"][offset : offset + 512]})
+        setup_ns = time.perf_counter_ns() - setup
+        phase = "warmup"
+        if job["case"] in ("select", "point", "wide"):
+            calls = len(job["rows"]) if job["case"] == "point" else 1
+            for row in job["rows"][:calls]:
+                output = db.execute(job["point"], {"id": row["id"]}) if job["case"] == "point" else db.execute(job["scan"])
+                # Existing result conversion is eager; merely retaining/dropping
+                # it warms the complete same binding/query path.
+                del output
+        query_ns = consume_ns = rows_seen = 0
+        checksum = Checksum(job["columns"])
+        phase = "execute"
+        profiling = hasattr(native, "_boundary_profile_snapshot")
+        if profiling:
+            import tracemalloc
+            tracemalloc.start()
+            native_before = native._boundary_profile_snapshot()
+        started = time.perf_counter_ns()
+        if job["case"] == "fill":
+            for row in job["rows"]:
+                called = time.perf_counter_ns()
+                db.execute(job["insert_single"], row)
+                query_ns += time.perf_counter_ns() - called
+        elif job["case"] == "fill_bulk":
+            called = time.perf_counter_ns()
+            db.execute(job["insert_bulk"], {"rows": job["rows"]})
+            query_ns += time.perf_counter_ns() - called
+        write_ns = query_ns
+        calls = len(job["rows"]) if job["case"] == "point" else 1
+        for row in job["rows"][:calls]:
+            called = time.perf_counter_ns()
+            output = db.execute(job["point"], {"id": row["id"]}) if job["case"] == "point" else db.execute(job["scan"])
+            query_ns += time.perf_counter_ns() - called
+            if output.columns != job["columns"]:
+                raise ValueError("result schema mismatch")
+            consumed = time.perf_counter_ns()
+            for result in output:
+                checksum.row([result[column] for column in job["columns"]])
+                rows_seen += 1
+            consume_ns += time.perf_counter_ns() - consumed
+        elapsed_ns = time.perf_counter_ns() - started
+        profile = None
+        if profiling:
+            native_after = native._boundary_profile_snapshot()
+            host_current, host_peak = tracemalloc.get_traced_memory()
+            tracemalloc.stop()
+            profile = native_delta(native_before, native_after)
+            profile["python_traced_current_bytes"] = host_current
+            profile["python_traced_peak_bytes"] = host_peak
+        return {
+            "status": "ok", "layer": "python", "case": job["case"], "backend": job["backend"],
+            "input_rows": len(job["rows"]), "output_rows": rows_seen,
+            "values": rows_seen * len(job["columns"]), "checksum": checksum.hex(),
+            "setup_ns": setup_ns, "query_boundary_ns": query_ns,
+            "write_boundary_ns": write_ns, "read_boundary_ns": query_ns - write_ns,
+            "consumer_ns": consume_ns, "elapsed_ns": elapsed_ns,
+            "native_profile": profile,
+            "durability": "SyncOnEveryWrite", "prefetch": 0,
+        }
+    except Exception as error:
+        return {"status": "error", "layer": "python", "phase": phase,
+                "error_type": type(error).__name__, "error": str(error)}
+    finally:
+        db.close()
+
+
+if __name__ == "__main__":
+    with open(sys.argv[1], encoding="utf-8") as source:
+        result = run(json.load(source))
+    result["peak_rss_bytes"] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
+    print(json.dumps(result, ensure_ascii=False))
diff --git a/bindings/benchmarks/run.py b/bindings/benchmarks/run.py
new file mode 100644
index 00000000..1133f803
--- /dev/null
+++ b/bindings/benchmarks/run.py
@@ -0,0 +1,306 @@
+# Copyright 2026 Nowledge
+# SPDX-License-Identifier: Apache-2.0
+
+"""Reproducible local Rust/Python/purego boundary matrix; never changes budgets.
+
+Build all native dependencies with the same Bazel optimization mode first:
+  bazel build -c opt //:hawdb_bench_host_boundary \
+    //bindings/benchmarks:python_boundary //bindings/go/cmd/boundary \
+    //bindings/ffi:hawdb_ffi
+"""
+
+import argparse
+import hashlib
+import json
+import os
+import pathlib
+import platform
+import re
+import statistics
+import subprocess
+import sys
+import time
+
+from checksum import Checksum
+
+ROOT = pathlib.Path(__file__).resolve().parents[2]
+CASES = ("select", "point", "fill", "fill_bulk", "wide")
+SEED = 0x5EED
+
+
+def dataset(count, wide):
+    state = SEED
+    for index in range(count):
+        state = (1664525 * state + 1013904223) & 0xFFFFFFFF
+        row = {"id": index, "score": (state >> 8) + 0.5,
+               "title": "mem-%08x-知识\x00🙂" % index}
+        if wide:
+            for column in range(3, 20):
+                kind = column % 7
+                row["c%02d" % column] = (
+                    -(state % 100000), (state % 10000) + 0.25,
+                    "thread-%d-界" % (index % 37), [index, None, "内容", True],
+                    {"id": index, "nested": ["\x00", False, {"标题": "value"}]},
+                    index % 2 == 0, None,
+                )[kind]
+        yield row
+
+
+def fixture(count, case):
+    rows = list(dataset(count, case == "wide"))
+    columns = sorted(rows[0])
+    properties = ", ".join("%s: row.%s" % (column, column) for column in columns)
+    projection = ", ".join("n.%s AS %s" % (column, column) for column in columns)
+    checksum = Checksum(columns)
+    for row in rows:
+        checksum.row([row[column] for column in columns])
+    return {
+        "case": case, "rows": rows, "columns": columns,
+        "insert_single": "CREATE (:Boundary {%s})" % ", ".join("%s: $%s" % (column, column) for column in columns),
+        "insert_bulk": "UNWIND $rows AS row CREATE (:Boundary {%s})" % properties,
+        "scan": "MATCH (n:Boundary) RETURN %s ORDER BY id" % projection,
+        "point": "MATCH (n:Boundary {id: $id}) RETURN %s" % projection,
+        "expected_checksum": checksum.hex(), "seed": SEED,
+    }
+
+
+def command_text(*args):
+    return subprocess.check_output(args, cwd=ROOT, text=True).strip()
+
+
+def source_identity():
+    # Staging is done by the caller before qualification. Detect modifications
+    # rather than silently giving evidence to whatever is compiled later.
+    if subprocess.run(["git", "diff", "--quiet"], cwd=ROOT).returncode:
+        raise RuntimeError("stage the final source before running the matrix")
+    if command_text("git", "ls-files", "--others", "--exclude-standard"):
+        raise RuntimeError("stage or remove untracked files before running the matrix")
+    return {"head": command_text("git", "rev-parse", "HEAD"),
+            "tree": command_text("git", "write-tree")}
+
+
+def artifact_identity(paths):
+    return {str(path): hashlib.sha256(path.read_bytes()).hexdigest() for path in paths}
+
+
+def require_artifact_identity(paths, expected):
+    if artifact_identity(paths) != expected:
+        raise RuntimeError("benchmark artifacts changed during qualification")
+
+
+def native_profile_valid(result, layer, required):
+    if result["status"] != "ok":
+        return None
+    profile = result.get("native_profile")
+    if not required:
+        # An instrumented artifact must not be reported as ordinary latency.
+        return profile is None
+    fields = ("allocation_calls", "allocated_bytes", "deallocation_calls",
+              "deallocated_bytes", "reallocation_calls",
+              "live_requested_bytes_before", "live_requested_bytes_after",
+              "process_peak_requested_bytes")
+    if layer != "rust":
+        fields += ("parameter_conversion_ns", "engine_call_ns", "result_conversion_ns")
+    return isinstance(profile, dict) and all(
+        type(profile.get(key)) is int and profile[key] >= 0 for key in fields
+    )
+
+
+def qualified_record(result):
+    return (result["status"] == "ok" and result["parity"]
+            and result["process_exit"] == 0 and result["profile_valid"] is True
+            and result["phase_timing_valid"] is True)
+
+
+def run_child(command, artifact):
+    started = time.monotonic()
+    timer = ["/usr/bin/time", "-l"] if sys.platform == "darwin" else ["/usr/bin/time", "-v"]
+    with artifact.with_suffix(".stdout").open("w") as stdout, artifact.with_suffix(".stderr").open("w") as stderr:
+        environment = os.environ.copy()
+        runfiles = pathlib.Path(command[0] + ".runfiles")
+        if runfiles.is_dir():
+            for key in ("RUNFILES_MANIFEST_FILE", "JAVA_RUNFILES", "PYTHONPATH", "PYTHONHOME"):
+                environment.pop(key, None)
+            environment.update(RUNFILES_DIR=str(runfiles), PYTHONDONTWRITEBYTECODE="1")
+        process = subprocess.Popen(timer + command, cwd=ROOT, stdout=stdout, stderr=stderr,
+                                   env=environment)
+        return_code = process.wait()
+    lines = artifact.with_suffix(".stdout").read_text().splitlines()
+    try:
+        result = json.loads(lines[-1])
+    except (ValueError, IndexError):
+        result = {"status": "process_error", "error": "missing result JSON"}
+    native = artifact.with_suffix(".stderr").read_text()
+    peak = re.search(r"(\d+)\s+maximum resident set size", native) if sys.platform == "darwin" else re.search(r"Maximum resident set size \(kbytes\):\s*(\d+)", native)
+    result.update({"process_exit": return_code, "process_seconds": time.monotonic() - started,
+                   "command": command, "stdout": str(artifact.with_suffix(".stdout")),
+                   "stderr": str(artifact.with_suffix(".stderr")),
+                   "process_peak_rss_bytes": int(peak[1]) * (1 if sys.platform == "darwin" else 1024) if peak else None})
+    return result
+
+
+def main():
+    parser = argparse.ArgumentParser(description=__doc__)
+    parser.add_argument("--output", type=pathlib.Path, required=True)
+    parser.add_argument("--sizes", default="1000,100000,1000000")
+    parser.add_argument("--cases", default=",".join(CASES))
+    parser.add_argument("--backends", default="memory,file")
+    parser.add_argument("--layers", default="rust,python,go")
+    parser.add_argument("--samples", type=int, default=3)
+    parser.add_argument("--rust", type=pathlib.Path, default=ROOT / "bazel-bin/hawdb_bench_host_boundary")
+    parser.add_argument("--python", type=pathlib.Path, default=ROOT / "bazel-bin/bindings/benchmarks/python_boundary")
+    parser.add_argument("--go", type=pathlib.Path)
+    parser.add_argument("--library", type=pathlib.Path)
+    parser.add_argument("--python-extension", type=pathlib.Path)
+    parser.add_argument("--native-profiles", action="store_true",
+                        help="require native counters from all three instrumented artifacts")
+    parser.add_argument("--cpu-profiles", action="store_true")
+    args = parser.parse_args()
+    sizes = [int(size) for size in args.sizes.split(",")]
+    cases = args.cases.split(",")
+    backends = args.backends.split(",")
+    layers = args.layers.split(",")
+    if args.samples < 1 or any(size < 1 for size in sizes) or set(cases) - set(CASES) or set(backends) - {"memory", "file"}:
+        parser.error("positive sizes/samples and known cases/backends are required")
+    if set(layers) - {"rust", "python", "go"} or len(set(layers)) != len(layers):
+        parser.error("known, distinct layers are required")
+    if args.native_profiles and args.python_extension is None:
+        parser.error("--native-profiles requires an explicit instrumented --python-extension")
+    args.output.mkdir(parents=True, exist_ok=False)
+    identity = source_identity()
+    if args.go is None:
+        # rules_go applies a pure-Go configuration transition, so its binary
+        # does not necessarily live under the root bazel-bin symlink.
+        args.go = ROOT / command_text("bazel", "cquery", "-c", "opt", "//bindings/go/cmd/boundary", "--output=files")
+    library = args.library or ROOT / "bazel-bin/bindings/ffi" / ("libhawdb_ffi.dylib" if sys.platform == "darwin" else "libhawdb_ffi.so")
+    args.rust, args.python, args.go, library = (path.resolve() for path in (args.rust, args.python, args.go, library))
+    # Freeze the extension as well: another Bazel configuration can retarget
+    # bazel-bin between jobs, but every job must load the hashed artifact.
+    if args.python_extension is None:
+        args.python_extension = pathlib.Path(str(args.python) + ".runfiles") / "_main/bindings/python/python/hawdb/_hawdb.so"
+    args.python_extension = args.python_extension.resolve()
+    if not args.python_extension.is_file():
+        parser.error("build the matching Python extension or pass --python-extension: " + str(args.python_extension))
+    commands = {"rust": [str(args.rust)], "python": [str(args.python)], "go": [str(args.go)]}
+    commands = {layer: commands[layer] for layer in layers}
+    for path in (args.rust, args.python, args.go, library):
+        if not path.is_file():
+            parser.error("build the matching benchmark first: " + str(path))
+    artifact_paths = (args.rust, args.python, args.go, library, args.python_extension)
+    artifacts = artifact_identity(artifact_paths)
+    report = {
+        "source": identity, "spec": "ZERO_COPY_COLUMNAR_INTERCHANGE_SPEC.md",
+        "seed": SEED, "sizes": sizes, "cases": cases, "backends": backends,
+        "layers": layers,
+        "samples": args.samples, "discarded_iterations": 1,
+        "os": platform.platform(), "machine": platform.machine(),
+        "cpu": command_text("sysctl", "-n", "machdep.cpu.brand_string") if sys.platform == "darwin" else platform.processor(),
+        "rust": command_text("rustc", "--version"), "go": command_text("go", "version"),
+        "build": "Bazel opt, all three engine dependencies compiled together",
+        "defaults_changed": False, "strict_zero_copy": False, "terminal": False,
+        "instrumented": args.native_profiles or args.cpu_profiles,
+        "native_profiles": args.native_profiles, "go_cpu_profiles": args.cpu_profiles,
+        "binaries": {layer: {"path": command[0], "sha256": artifacts[command[0]]} for layer, command in commands.items()},
+        "library_sha256": artifacts[str(library)],
+        "python_extension_path": str(args.python_extension),
+        "python_extension_sha256": artifacts[str(args.python_extension)],
+        "records": [], "summaries": [],
+        "measurement_limits": [
+            "A selected layer/backend shard qualifies only its recorded groups; full-matrix acceptance requires complete coverage across shards.",
+            "Process peak RSS includes runtime, fixture, setup and query; it is not a query-only allocation ledger.",
+            "Allocator observations count Rust requests; Go/Python heaps and non-Rust workspace are separate." if args.native_profiles else "Go allocation counts exclude the native engine; run the separately instrumented matrix for native/Python profiles.",
+            "Each iteration opens its own store; seeded read runs measure a warm store, not cold artifact reads.",
+            "Write cases include a final verification query in query_boundary_ns; write_boundary_ns and read_boundary_ns separate the phases without removing calls.",
+            "The query timer excludes the identical checksum algorithm; consumer time is reported separately.",
+        ],
+    }
+    destination = args.output / "report.json"
+    def save():
+        destination.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n")
+    def check_artifacts():
+        try:
+            require_artifact_identity(artifact_paths, artifacts)
+        except (OSError, RuntimeError) as error:
+            report["qualification_error"] = str(error)
+            save()
+            raise
+    save()
+    parity_failures = 0
+    for count in sizes:
+        for case in cases:
+            data = fixture(count, case)
+            for backend in backends:
+                for iteration in range(args.samples + 1):
+                    # Rotate the layer order deterministically to avoid always
+                    # giving one binding the first/cold CPU scheduling position.
+                    layers = list(commands)
+                    offset = iteration % len(layers)
+                    for layer in layers[offset:] + layers[:offset]:
+                        if source_identity() != identity:
+                            raise RuntimeError("source changed during qualification")
+                        check_artifacts()
+                        stem = "%s-%s-%d-%s-%d" % (layer, case, count, backend, iteration)
+                        job_path = args.output / (stem + ".job.json")
+                        job = dict(data, backend=backend, path=str(args.output / (stem + ".db")))
+                        if args.cpu_profiles and layer == "go":
+                            job["cpu_profile_path"] = str(args.output / (stem + ".cpu.pprof"))
+                        job_path.write_text(json.dumps(job, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
+                        command = commands[layer] + [str(job_path)] + ([str(library)] if layer == "go" else [])
+                        if layer == "python":
+                            command.append(str(args.python_extension))
+                        result = run_child(command, args.output / stem)
+                        result.update({"layer": layer, "case": case, "size": count, "backend": backend, "iteration": iteration,
+                                       "discarded": iteration == 0, "fixture_sha256": hashlib.sha256(job_path.read_bytes()).hexdigest(),
+                                       "expected_checksum": data["expected_checksum"]})
+                        if result["status"] == "ok":
+                            result["parity"] = result.get("checksum") == data["expected_checksum"] and result.get("output_rows") == count
+                            parity_failures += not result["parity"]
+                        else:
+                            result["parity"] = None
+                        timings = ("query_boundary_ns", "write_boundary_ns", "read_boundary_ns")
+                        result["phase_timing_valid"] = (
+                            all(type(result.get(key)) is int and result[key] >= 0 for key in timings)
+                            and result["query_boundary_ns"] == result["write_boundary_ns"] + result["read_boundary_ns"]
+                            and (case in ("fill", "fill_bulk") or result["write_boundary_ns"] == 0)
+                        ) if result["status"] == "ok" else None
+                        result["profile_valid"] = native_profile_valid(result, layer, args.native_profiles)
+                        report["records"].append(result)
+                        save()
+                        # Preserve the child's raw outcome even if a rebuild
+                        # happened during it. Such a report remains nonterminal.
+                        check_artifacts()
+                        print(stem, result["status"], result["parity"], flush=True)
+                        job_path.unlink()  # retain hashes/inputs recipe, not many identical giant fixtures
+                        if backend == "file":
+                            import shutil
+                            shutil.rmtree(job["path"], ignore_errors=False) if pathlib.Path(job["path"]).exists() else None
+                for layer in commands:
+                    records = [r for r in report["records"] if r["case"] == case and r["size"] == count and r["backend"] == backend and r["layer"] == layer and not r["discarded"]]
+                    valid = [r for r in records if qualified_record(r)]
+                    report["summaries"].append({"layer": layer, "case": case, "size": count, "backend": backend,
+                        "successful_samples": len(valid), "failed_samples": len(records) - len(valid),
+                        "median_query_boundary_ns": statistics.median(r["query_boundary_ns"] for r in valid) if valid else None,
+                        "median_write_boundary_ns": statistics.median(r["write_boundary_ns"] for r in valid) if valid else None,
+                        "median_read_boundary_ns": statistics.median(r["read_boundary_ns"] for r in valid) if valid else None,
+                        "median_elapsed_ns": statistics.median(r["elapsed_ns"] for r in valid) if valid else None})
+                save()
+            del data
+    if source_identity() != identity:
+        raise RuntimeError("source changed before completion")
+    check_artifacts()
+    report.update(terminal=True, parity_failures=parity_failures,
+                  value_parity_records=sum(r["status"] == "ok" and r["parity"] for r in report["records"]),
+                  successful_records=sum(qualified_record(r) for r in report["records"]),
+                  refused_or_failed_records=sum(r["status"] != "ok" for r in report["records"]))
+    save()
+    # A completed experiment may contain useful budget-refusal evidence, but
+    # cannot be represented as a successful parity/performance qualification.
+    report["profile_failures"] = sum(r["profile_valid"] is False for r in report["records"])
+    report["phase_timing_failures"] = sum(r["phase_timing_valid"] is False for r in report["records"])
+    report["all_paths_succeeded"] = all(qualified_record(r) for r in report["records"])
+    save()
+    return int(not report["all_paths_succeeded"])
+
+
+if __name__ == "__main__":
+    sys.exit(main())
diff --git a/bindings/ffi/BUILD.bazel b/bindings/ffi/BUILD.bazel
index b8fa6743..62a16398 100644
--- a/bindings/ffi/BUILD.bazel
+++ b/bindings/ffi/BUILD.bazel
@@ -29,3 +29,20 @@ rust_static_library(
     version = "0.6.0",
     deps = _FFI_DEPS,
 )
+
+# Local profiling only; not a replacement library or a default/CI dependency.
+rust_shared_library(
+    name = "hawdb_ffi_boundary_profile",
+    srcs = glob(["src/**/*.rs"]) + ["//bindings/benchmarks:native_alloc.rs", "//bindings/benchmarks:native_profile.rs"],
+    crate_name = "hawdb_ffi_boundary_profile",
+    crate_root = "src/lib.rs",
+    crate_features = ["boundary-profiling"],
+    edition = "2024",
+    rustc_flags = select({
+        "@platforms//os:macos": ["-Cstrip=none"],
+        "//conditions:default": [],
